import { BarChart } from '@/react/components/ui/BarChart'
import { ChartTrend } from '@/react/components/ui/ChartTrend'
import { type DayPoint, formatNumber, totalOf, weekChange } from '@/react/hooks/useChart'
// The usage page's cards: a meter's total for the month, the week's change and its bars per day, with the grid and
// the dates. Point at a bar to read it.
const days = Array.from({ length: 30 }, (_, i) => `2026-10-${String(i + 2).padStart(2, '0')}`)
const series = (peak: number, step: number): DayPoint[] => days.map((day, i) => ({ day, value: Math.round(peak * (0.16 + (((i * step) % 23) / 23) ** 2 * 0.84)) }))
const metrics = [
  { key: 'queries', label: 'Queries', points: series(15000, 7) },
  { key: 'documents', label: 'Documents written', points: series(13000, 11) },
]

export default function Usage() {
  return (
    <ul className="grid gap-4 md:grid-cols-2">
      {metrics.map(m => (
        <li key={m.key} className="flex flex-col gap-8 border border-edge bg-surface p-4">
          <div className="flex items-start justify-between gap-3">
            <div>
              <p className="type-meta text-fg-muted">{m.label}</p>
              <p className="text-heading-4 font-medium tabular-nums">{formatNumber(totalOf(m.points))}</p>
            </div>
            {weekChange(m.points) !== null && <ChartTrend change={weekChange(m.points)!} />}
          </div>
          <BarChart points={m.points} label={`${m.label} per day`} height={120} bare />
        </li>
      ))}
    </ul>
  )
}

import { LineChart } from '@/react/components/ui/LineChart'
// Search latency, p50 and p95, as smoothed lines over a day.
const hour = (i: number) => Date.UTC(2026, 9, 29, i)
const latency = [
  { label: 'p50', points: Array.from({ length: 24 }, (_, i) => ({ t: hour(i), v: 230 + ((i * 13) % 7) * 3 })) },
  { label: 'p95', points: Array.from({ length: 24 }, (_, i) => ({ t: hour(i), v: 400 + ((i * 17) % 9) * 6 })) },
]
const ms = (v: number) => `${Math.round(v)} ms`

export default function Product() {
  return <LineChart title="Search latency, last 24 hours" series={latency} format={ms} smooth={3} bare />
}

import { Meter } from '@/react/components/ui/Meter'
import { Table } from '@/react/components/ui/Table'
import { formatNumber } from '@/react/hooks/useChart'
// What drives a total: each row's share as a bar, the largest red. Point at a row, or focus it, and its percent rolls
// up to what it cost.
const lines = [
  { name: 'sec-filings', queries: 50908, share: 21, cost: '$26.59' },
  { name: 'contracts', queries: 33658, share: 14, cost: '$17.58' },
  { name: 'slack', queries: 18317, share: 7, cost: '$9.57' },
  { name: 'crm', queries: 14127, share: 6, cost: '$7.38' },
]

export default function Share() {
  return (
    <>
      <style href="ds-example-share" precedence="ds">{css}</style>
      <Table framed label="share of credits used">
        <thead><tr><th className="sm:w-40">Namespace</th><th><span className="sr-only">Share bar</span></th><th className="w-24 text-right">Queries</th><th className="w-32 text-right">% of credits used</th></tr></thead>
        <tbody>
          {lines.map((l, i) => (
            <tr key={l.name} className="share-row" tabIndex={0}>
              <td className="type-code-sm">{l.name}</td>
              <td><Meter value={l.share * 3} tone={i ? 'default' : 'top'} decorative /></td>
              <td className="text-right tabular-nums">{formatNumber(l.queries)}</td>
              <td className="text-right font-medium tabular-nums">
                <span className="share-roll"><span className="share-a">{`${l.share}%`}</span><span className="share-b">{l.cost}</span></span>
              </td>
            </tr>
          ))}
        </tbody>
      </Table>
    </>
