import { html, nothing, svg } from 'lit'
import { DsElement, define } from '@/elements/lib/element'
import styles from 'virtual:tw'

// TrendArrow.vue as <conare-trend-arrow>: the way a number moved, in the website button's pixel arrow
// (usage/TrendArrow.vue): lit squares on a grid of dim ones, red going up, ink going down (turned over). `bare` is a
// solid pixel triangle with no grid, for beside a stat. It holds still: icons never move on hover.

const CELL = 3
const SIZE = 5
const GRID = Array.from({ length: SIZE * SIZE }, (_, k) => [k % SIZE, Math.floor(k / SIZE)] as const)
// [column, row] of the lit squares, pointing up.
const ARROW: Array<[number, number]> = [[2, 0], [1, 1], [2, 1], [3, 1], [0, 2], [2, 2], [4, 2], [2, 3], [2, 4]]
const TRIANGLE: Array<[number, number]> = [[2, 0], [1, 1], [2, 1], [3, 1], [0, 2], [1, 2], [2, 2], [3, 2], [4, 2]]

/** @summary A pixel arrow: red going up, ink going down. */
export class TrendArrow extends DsElement {
	static styles = [DsElement.styles, styles]
	static properties = { down: { type: Boolean }, bare: { type: Boolean } }

	/** Going down: ink, turned over. */
	down = false
	/** A solid triangle with no grid, beside a stat. */
	bare = false

	render() {
		const bare = this.bare
		const rows = bare ? 3 : SIZE
		const ink = bare ? CELL : 2
		const wide = SIZE * CELL - (bare ? 0 : 1)
		const tall = rows * CELL - (bare ? 0 : 1)
		const lit = bare ? TRIANGLE : ARROW
		return html`<svg data-ds="trend-arrow" class=${['shrink-0 overflow-hidden', this.down ? 'rotate-180' : ''].join(' ')} width=${wide} height=${tall} viewBox=${`0 0 ${wide} ${tall}`} aria-hidden="true">
			${bare ? nothing : svg`<g class="fill-ds-neutral-700">${GRID.map(([x, y]) => svg`<rect x=${x * CELL} y=${y * CELL} width="2" height="2"></rect>`)}</g>`}
			<g class=${this.down ? 'fill-fg' : 'fill-edge-accent'}>${lit.map(([x, y]) => svg`<rect x=${x * CELL} y=${y * CELL} width=${ink} height=${ink}></rect>`)}</g>
		</svg>`
	}
}

define('trend-arrow', TrendArrow)

import { html, nothing, type PropertyValues } from 'lit'
import { repeat } from 'lit/directives/repeat.js'
import { ifDefined } from 'lit/directives/if-defined.js'
import { DsElement, define } from '@/elements/lib/element'
import styles from 'virtual:tw'

// SplitBar.vue as <conare-split-bar>: a whole in parts, as Billing's prices draw it (the chart's Split example): one
// bar, the parts in the order given (largest first), the picked part in ink with a red mark gliding over it; under it
// the parts as rows in a card, one paper block gliding to the row under the pointer or focus, and a red square on the
// picked row. Pointing at a row picks it (v-model is `value` with `input` and `change`). `detail` is a quiet middle
// column, hidden on phones; `display` is the value as written.
export type SplitPart = { name: string, value: number, display?: string, detail?: string }

/**
 * @summary A whole in parts: one bar over a card of rows, the picked part marked.
 * @fires input - The picked part changed (read `value`, its index).
 * @fires change - The picked part changed.
 */
export class SplitBar extends DsElement {
	static styles = [DsElement.styles, styles]
	static properties = { parts: { type: Array }, label: {}, value: { type: Number }, mark: { state: true }, instant: { state: true } }

	/** [{ name, value, display?, detail? }], largest first. */
	parts: SplitPart[] = []
	/** The rows' name. */
	label?: string
	/** The picked part's index. */
	value = 0
	private mark: { y: number, h: number } | null = null
	private instant = true

	// The gliding block: placed at once the first time, then it glides on transform.
	private place(i: number) {
		const row = this.renderRoot.querySelectorAll<HTMLElement>('[data-glide-row]')[i]
		if (!row) return
		this.instant = !this.mark
		this.mark = { y: row.offsetTop, h: row.offsetHeight }
	}
	private pick(i: number) {
		if (this.value !== i) this.commit(i)
		this.place(i)
	}
	protected updated(changed: PropertyValues) {
		super.updated(changed)
		if (changed.has('value') || changed.has('parts')) this.place(this.value)
	}

	render() {
		const parts = this.parts ?? []
		const total = parts.reduce((a, p) => a + p.value, 0) || 1
		// The parts share what the bar's 2px gaps leave, so those come out of the percent.
		const n = parts.length
		const i = Math.min(this.value, n - 1)
		const middle = (parts.slice(0, i).reduce((a, p) => a + p.value, 0) + (parts[i]?.value ?? 0) / 2) / total
		const center = `calc(${middle * 100}% + ${i * 2 - middle * 2 * (n - 1)}px)`
		const on = (k: number) => ifDefined(this.value === k ? 'true' : undefined)
		return html`<div data-ds="split-bar" class="flex flex-col gap-4">
			<div class="ds-segmark-track" aria-hidden="true"><span class="ds-segmark" style=${`transform: translateX(${center})`}><i></i></span></div>
			<div class="ds-splitbar" aria-hidden="true">${repeat(parts, (p) => p.name, (p, k) => html`<span data-on=${on(k)} style=${`flex-grow: ${p.value / total}`}></span>`)}</div>
			<ul class="relative border border-edge bg-surface" aria-label=${ifDefined(this.label)}>
				${this.mark ? html`<span class="ds-rowmark" data-instant=${ifDefined(this.instant ? 'true' : undefined)} style=${`transform: translateY(${this.mark.y}px); height: ${this.mark.h}px`} aria-hidden="true"></span>` : nothing}
				${repeat(parts, (p) => p.name, (p, k) => html`<li data-glide-row class="border-edge [&+&]:border-t"><button type="button" class="ds-priced" data-on=${on(k)} aria-pressed=${String(this.value === k)} @pointerenter=${() => this.pick(k)} @focus=${() => this.pick(k)} @click=${() => this.pick(k)}><span class="min-w-0 flex-1 truncate text-left">${p.name}</span>${p.detail ? html`<span class="hidden text-fg-muted tabular-nums sm:inline">${p.detail}</span>` : nothing}<span class="w-24 text-right tabular-nums">${p.display ?? p.value.toLocaleString('en-US')}</span></button></li>`)}
			</ul>
		</div>`
	}
}

define('split-bar', SplitBar)

/* console2.css .v2-splitbar, .v2-segmark, .v2-rowmark and .v2-priced, as Billing's prices set them (data-pm="6"). */
.ds-splitbar { display: flex; height: 12px; gap: var(--ds-space-2xs); margin-top: var(--ds-space-xs); }
.ds-splitbar > span { flex-basis: 0; background: var(--ds-color-neutral-600); transition: background-color var(--ds-duration-micro) var(--ds-easing-standard); }
.ds-splitbar > span[data-on] { background: var(--ds-color-surface-inverse); }
.ds-segmark-track { position: relative; height: 8px; margin-bottom: -12px; overflow: clip; }
.ds-segmark { position: absolute; inset: 0; transition: transform var(--ds-duration-settle) var(--ds-easing-out); }
.ds-segmark i { position: absolute; top: 0; left: -3px; width: 6px; height: 6px; background: var(--ds-color-edge-accent); }
.ds-rowmark { position: absolute; top: 0; right: 0; left: 0; z-index: 0; background: var(--ds-color-surface-subtle); pointer-events: none; transition: transform var(--ds-duration-enter) var(--ds-easing-out), height var(--ds-duration-enter) var(--ds-easing-out); }
.ds-rowmark[data-instant] { transition: none; }
.ds-priced { position: relative; z-index: 1; display: flex; width: 100%; min-height: var(--ds-size-row); align-items: center; gap: var(--ds-space-xl); padding: 0 16px 0 20px; font-size: var(--ds-text-ui); cursor: pointer; }
.ds-priced::before { position: absolute; top: 50%; left: 8px; width: 4px; height: 4px; margin-top: -2px; background: var(--ds-color-edge-accent); content: ""; opacity: 0; transition: opacity var(--ds-duration-micro) var(--ds-easing-standard); }
.ds-priced[data-on]::before { opacity: 1; }
.ds-priced:focus-visible { outline: var(--ds-border-focus) solid var(--ds-color-edge-accent); outline-offset: -2px; }
@media (prefers-reduced-motion: reduce) { .ds-splitbar > span, .ds-segmark, .ds-rowmark { transition: none; } }

// What the charts share (usageMetrics.ts, BarChart.vue): numbers in en-US, an axis that ends on a round number in four
// steps, and the week's change.
// They are plain functions (Vue's useChart.ts as it is), bundled into each chart element that uses them.

export type DayPoint = { day: string, value: number }
export type ChartMetric = { key: string, label: string, points: DayPoint[] }

const whole = new Intl.NumberFormat('en-US')
const compact = new Intl.NumberFormat('en-US', { notation: 'compact', maximumFractionDigits: 1 })

/** 186402 -> "186,402". */
export const formatNumber = (n: number) => whole.format(n)
/** 186402 -> "186.4K", for axis labels. */
export const compactNumber = (n: number) => compact.format(n)

/** The axis: a step of 1, 2, 2.5 or 5 times a power of ten that covers the largest value in four. Starts at 0. */
export function niceTicks(values: number[]) {
	const max = Math.max(0, ...values)
	if (max === 0) return [0, 1]
	const raw = max / 4
	const power = 10 ** Math.floor(Math.log10(raw))
	const step = ([1, 2, 2.5, 5, 10].find(m => m * power >= raw) ?? 10) * power
	return Array.from({ length: Math.ceil(max / step) + 1 }, (_, i) => i * step)
}

/** "Oct 2", or "Oct 2, 2026" with the year, from an ISO day. */
export const formatDay = (value: string, year = false) => new Date(`${value}T00:00:00Z`).toLocaleDateString('en-US', { month: 'short', day: 'numeric', ...(year ? { year: 'numeric' } : {}), timeZone: 'UTC' })

/** The sum of a metric's points over its range. */
export const totalOf = (points: DayPoint[]) => points.reduce((a, p) => a + p.value, 0)

/** The last seven days against the seven before, as a share; null without both. */
export function weekChange(points: DayPoint[]): number | null {
	if (points.length < 14) return null
	const before = totalOf(points.slice(-14, -7))
	return before ? (totalOf(points.slice(-7)) - before) / before : null
}
